-- Airlinerra Phase 5 Batch 7 — 36 runway direction source observations, saved on 2026-10-26.
-- Replay requires the mixed-pavement and prohibited-landing-direction check migration,
-- docs/sql/AIRLINERRA_PHASE5_BATCH_07_DIRECTION_RESTRICTION_MIGRATION_2026-10-26.sql
-- No official FAA direction-specific LDA values obtained in this batch.
-- At LAM, runway 09 is marked LANDING_DIRECTION_PROHIBITED and runway 27 is LDA_UNVERIFIED.
-- Hayward HWD runway 10R has 826ft displacement in FAA-derived current listing vs 816ft on City of Hayward webpage.
-- All rows remain commercial_admission_status NOT_APPROVED; conflicts are protected from overwrites.
ON CONFLICT (airport_key,runway_end) DO NOTHING;

SELECT p.faa_identifier,d.runway_end,d.screening_status,d.source_surface,d.source_cycle_date,d.commercial_admission_status
FROM airlinerra.airport_expansion_phase5_runway_directions d
JOIN airlinerra.airport_expansion_phase5_gate_reviews p USING(airport_key)
WHERE p.phase5_batch_identifier='US_EXPANSION_PHASE5_MISSING_LDA_BATCH_07_2026_10_26'
ORDER BY p.faa_identifier,d.runway_end;
